from youtube_dl.extractor.common import InfoExtractor

class Downloader:
    params = {}
    def __init__(self):
        self.requests = []
    def to_screen(self, message):
        pass
    def urlopen(self, request):
        self.requests.append(request)
        return object()

downloader = Downloader()
ie = InfoExtractor(downloader)
ie._x_forwarded_for_ip = '203.0.113.7'
ie._request_webpage('http://example.test/one', 'one')
ie._x_forwarded_for_ip = None
ie._request_webpage('http://example.test/two', 'two')
assert not any(key.lower() == 'x-forwarded-for' for key, value in downloader.requests[1].header_items())
